@property
def maintainers(self) -> list[str]:
    """
    https://peps.python.org/pep-0621/#authors-maintainers
    """
    maintainers: list[str]

    if self._maintainers is None:
        if "maintainers" in self.config:
            maintainers = self.config["maintainers"]
