                """
                from hatch.env.collectors.plugin.interface import EnvironmentCollectorInterface

                class CustomHook(EnvironmentCollectorInterface):
                    def finalize_config(self, config):
                        config['default']['type'] = 'foo'
                """
            )
        )

        env_config = {
