        normalized_phase, _ = _parse_letter_version(phase, 0)
        assert scheme.update(phase, "9000.0.0.post7.dev5", {}) == f"9000.0.0{normalized_phase}0"

    @pytest.mark.parametrize("phase", ["a", "b", "c", "rc", "alpha", "beta", "pre", "preview"])
